package com.iamgasgass.gassplayer.services
import com.iamgasgass.gassplayer.network.HttpClient
import kotlinx.serialization.json.*
import okhttp3.*
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
class TraktService(private val http:HttpClient,private val clientId:String,private val clientSecret:String){data class DeviceCode(val code:String,val userCode:String,val verificationUrl:String,val expires:Int,val interval:Int);private val json=Json{ignoreUnknownKeys=true};private suspend fun post(path:String,body:String,token:String="")=withContext(Dispatchers.IO){val b=Request.Builder().url("https://api.trakt.tv$path").header("Content-Type","application/json").header("trakt-api-version","2").header("trakt-api-key",clientId);if(token.isNotBlank())b.header("Authorization","Bearer $token");OkHttpClient().newCall(b.post(body.toRequestBody("application/json".toMediaType())).build()).execute().use{val value=it.body?.string().orEmpty();if(!it.isSuccessful)error("Trakt HTTP ${it.code}: $value");value}};suspend fun deviceCode():DeviceCode{val o=json.parseToJsonElement(post("/oauth/device/code",buildJsonObject{put("client_id",clientId)}.toString())).jsonObject;return DeviceCode(o.s("device_code"),o.s("user_code"),o.s("verification_url"),o.i("expires_in"),o.i("interval"))};suspend fun exchange(code:String):String{val body=buildJsonObject{put("code",code);put("client_id",clientId);put("client_secret",clientSecret)}.toString();return json.parseToJsonElement(post("/oauth/device/token",body)).jsonObject.s("access_token")};suspend fun scrobble(token:String,title:String,progress:Double,state:String="start"){post("/scrobble/$state",buildJsonObject{putJsonObject("movie"){put("title",title)};put("progress",progress.coerceIn(0.0,100.0))}.toString(),token)}}
private fun JsonObject.s(k:String)=this[k]?.jsonPrimitive?.contentOrNull.orEmpty();private fun JsonObject.i(k:String)=this[k]?.jsonPrimitive?.intOrNull?:0
